x, with the Euclidean density e and Lebesgue measure dx specified above.\", \"depends_on\": [\"D001\", \"D003\"], \"requires\": [\"H002\", \"N002\"], \"binders\": [{\"symbol\": \"t\", \"type\": \"positive real time\"}, {\"symbol\": \"x\", \"type\": \"integration variable in ℝ^n\"}], \"objects\": [\"e\", \"n\", \"dx\", \"t\", \"x\"]}], \"logic\": {\"classical\": true, \"rules\": [\"direct\", \"forall_introduction\", \"implication_introduction\", \"exists_elimination\", \"case_elimination\"], \"calculations\": [\"equality\", \"definitions\", \"finite_algebra\", \"finite_order\", \"finite_sums\"], \"primitives\": [{\"symbol\": \"0\", \"type\": \"typed numeral\", \"meaning\": \"Zero of the explicitly specified mathematical type.\"}, {\"symbol\": \"1\", \"type\": \"typed numeral\", \"meaning\": \"One of the explicitly specified mathematical type.\"}, {\"symbol\": \"2\", \"type\": \"typed numeral\", \"meaning\": \"Two of the explicitly specified mathematical type, including an exponent two.\"}, {\"symbol\": \"ℕ\", \"type\": \"number system\", \"meaning\": \"The natural numbers with their usual arithmetic.\"}, {\"symbol\": \"ℤ\", \"type\": \"number system\", \"meaning\": \"The integers with their usual arithmetic.\"}, {\"symbol\": \"ℚ\", \"type\": \"number system\", \"meaning\": \"The rational numbers with their usual ordered-field operations.\"}, {\"symbol\": \"ℝ\", \"type\": \"number system\", \"meaning\": \"The real numbers with their usual ordered-field structure.\"}, {\"symbol\": \"ℂ\", \"type\": \"number system\", \"meaning\": \"The complex numbers with their usual field structure.\"}, {\"symbol\": \"∅\", \"type\": \"typed set notation\", \"meaning\": \"The empty set in the explicitly specified ambient type.\"}, {\"symbol\": \"∞\", \"type\": \"typed order notation\", \"meaning\": \"The top element in an explicitly specified extended ordered codomain.\"}]}, \"pins\": {\"lean_version\": \"4.32.2\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"mathlib_root\": \"/Users/syyui/formalization-tools/lean-mathlib-v4.32.2/mathlib\"}, \"inputs\": [{\"path\": \"inputs/problem.md\", \"sha256\": \"e858e20c3c50892224d315966ffed960bc0a4713ce9d2b9a3139dc84b49600ac\"}, {\"path\": \"inputs/target-selection.json\", \"sha256\": \"cf8a3fd5843e49a61f8e2312f225f3201985ed22c1a7d8cea7f7c8a08ea3229d\"}]}, \"has_more\": false, \"next_offset\": null}"}}
